def _normalize(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return frozenset((r - min_r, c - min_c) for r, c in cells)


def transform(grid):
    h, w = len(grid), len(grid[0])
    wall = grid[0][0]
    # The initial solid run on the top divider is the framed panel width.
    panel_w = 0
    while panel_w < w and grid[0][panel_w] == wall:
        panel_w += 1

    dividers = [r for r in range(h) if all(grid[r][c] == wall for c in range(panel_w))]
    out = [row[:panel_w] for row in grid]

    # Collect each colored object to the right of the panel, by connected component.
    unseen = {(r, c) for r in range(h) for c in range(panel_w, w)
              if grid[r][c] not in (0, wall)}
    objects = []
    while unseen:
        start = next(iter(unseen))
        color = grid[start[0]][start[1]]
        q = [start]
        unseen.remove(start)
        cells = {start}
        while q:
            r, c = q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen and grid[p[0]][p[1]] == color:
                    unseen.remove(p)
                    cells.add(p)
                    q.append(p)
        objects.append((color, _normalize(cells)))

    for top, bottom in zip(dividers, dividers[1:]):
        holes = {(r, c) for r in range(top + 1, bottom)
                 for c in range(1, panel_w - 1) if grid[r][c] == 0}
        if not holes:
            continue
        shape = _normalize(holes)
        matches = [color for color, obj_shape in objects if obj_shape == shape]
        if len(matches) != 1:
            raise ValueError(f"Expected one matching object for cavity {shape}; got {matches}")
        for r, c in holes:
            out[r][c] = matches[0]
    return out
